fn gcd(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> gcd(3, 5)
    1
    >>> gcd(25, 15)
    5
    """
    fn euclid(a: int, b: int) -> int:
        """ Euclid's algorithm for gcd """
        if b == 0:
            return a
        return euclid(b, a % b)
    return euclid(a, b)

