    """
    Write a function to find the index of the first occurrence of a given number in a sorted array.
    """
    var low = 0
    var high = len(A) - 1
    while low <= high:
        var mid = (low + high) / 2
        if A[mid] == x:
            if mid == 0 or A[mid - 1] != x:
                return mid
            high = mid - 1
        elif A[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

