fn shell_sort(my_list: [int]) -> [int]:
    var gap = len(my_list) / 2
    while gap > 0:
        for i in range(gap, len(my_list)):
            var temp = my_list[i]
            var j = i
            while j >= gap:
                if my_list[j - gap] > temp:
                    my_list[j] = my_list[j - gap]
                    j -= gap
                else:
                    break
            my_list[j] = temp
        gap = gap / 2
    return my_list

